const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',qr:'M3 3h6v6H3z M15 3h6v6h-6z M3 15h6v6H3z M15 15h2v2h-2z M20 14v3 M14 20h3 M20 20h1',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M17 4a4 4 0 0 1 0 7 M22 21v-2a4 4 0 0 0-3-4',check:'M5 12l4 4L19 6',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',book:'M3 4h7l2 2 2-2h7v16h-7l-2 2-2-2H3z M12 6v16',chart:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',plus:'M12 5v14 M5 12h14',arrow:'M5 12h14 M14 7l5 5-5 5',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 11h16',out:'M9 4H4v16h5 M13 8l4 4-4 4 M8 12h13',menu:'M4 6h16 M4 12h16 M4 18h16',download:'M12 3v12 M7 10l5 5 5-5 M4 16v5h16v-5',heart:'M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-4 5 2 10 8 15 6-5 12-10 8-15',bell:'M6 9a6 6 0 0 1 12 0v7l2 2H4l2-2z M10 21h4',close:'M6 6l12 12 M18 6 6 18',shield:'M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z M8 12l3 3 5-6'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.grid}"/></svg>`;
const labels={pending:'Pendente',approved:'Aprovado',rejected:'Rejeitado',correction:'Correção solicitada',present:'Presente',absent:'Ausente',unregistered:'Não registrado',yes:'Sim',no:'Não',unknown:'Não informado',open:'Em andamento',closed:'Encerrada'};
const badge=s=>`<span class="badge ${esc(s)}">${labels[s]||esc(s)}</span>`;
const date=s=>s?new Date(s.length===10?s+'T12:00:00':s).toLocaleDateString('pt-BR'):'—';
const time=s=>s?new Date(s).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}):'—';
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'America/Sao_Paulo'}).format(new Date());
const initials=n=>n.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('');
let me,classes=[],students=[],calls=[],scanner,routeVersion=0;
async function api(path,method='GET',data){const res=await fetch('/api'+path,{method,headers:{'Content-Type':'application/json',...(me?{'X-CSRF-Token':me.csrf}:{})},...(data?{body:JSON.stringify(data)}:{})});const body=await res.json();if(!res.ok){if(res.status===401&&me){me=null;stopCamera();location.hash='login';}throw new Error(body.error||'Não foi possível concluir.');}return body;}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function go(route){if(location.hash.slice(1)===route)render();else location.hash=route;}
function stopCamera(){scanner?.stop();scanner=null;document.querySelectorAll('video').forEach(v=>{v.srcObject?.getTracks().forEach(t=>t.stop());v.srcObject=null;});}
const button=(label,action,kind='',ic='')=>`<button class="${kind}" data-action="${action}">${ic?icon(ic):''}${label}</button>`;
function modal(title,html){const d=$('#dialog');d.innerHTML=`<div class="panel-head"><h2>${title}</h2>${button('','close','ghost','close')}</div>${html}`;if(!d.open)d.showModal();return d;}
function formModal(title,fields,submit,onSubmit){modal(title,`<form id="modal-form">${fields}<div class="form-error" role="alert"></div><div class="actions">${button('Cancelar','close') }<button class="primary" type="submit">${submit}</button></div></form>`);$('#modal-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await onSubmit(Object.fromEntries(new FormData(e.target)));$('#dialog').close();await render();}catch(err){$('#modal-form .form-error').textContent=err.message;}finally{b.disabled=false;}};$('#modal-form [data-action=close]').type='button';}
function classOptions(value,activeOnly=false){return classes.filter(c=>!activeOnly||c.active).map(c=>`<option value="${c.id}" ${Number(value)===c.id?'selected':''}>${esc(c.name)}</option>`).join('');}
const brand=`<a class="brand" href="#home"><span class="brand-mark">${icon('qr')}</span><span>presença<small>Cada encontro conta</small></span></a>`;
function shell(content,active='home'){
 const nav=[['home','grid','Visão geral'],['call','qr','Fazer chamada'],['pending','clock','Cadastros pendentes'],['students','users','Alunos'],['classes','book','Turmas'],['history','calendar','Histórico'],['reports','chart','Relatórios']];
 $('#app').innerHTML=`<div class="layout"><div class="menu-backdrop" data-action="close-menu" hidden></div><aside class="sidebar" id="sidebar">${button('Fechar menu','close-menu','mobile-menu sidebar-close','close')}${brand}<div class="nav-caption">${me.role==='teacher'?'Gestão da catequese':'Área do aluno'}</div><nav class="nav">${(me.role==='teacher'?nav:[['home','grid','Meu painel']]).map(([r,i,t])=>`<a href="#${r}" class="${r===active?'active':''}">${icon(i)}${t}${r==='pending'&&students.filter(s=>['pending','correction'].includes(s.status)).length?`<span class="count">${students.filter(s=>['pending','correction'].includes(s.status)).length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-note">${icon('heart')}<strong>Mais tempo para o que importa.</strong>Menos tempo na chamada, mais presença em cada encontro.</div><div class="profile"><div class="avatar">${esc(initials(me.name))}</div><div><strong>${esc(me.name.split(' ').slice(0,2).join(' '))}</strong><br><small>${me.role==='teacher'?'Professor(a)':'Aluno(a)'}</small></div><button class="ghost" data-action="logout" title="Sair">${icon('out')}</button></div></div></aside><main class="main"><header class="topbar"><div class="actions"><button class="mobile-menu ghost" data-action="menu" aria-label="Abrir menu" aria-controls="sidebar" aria-expanded="false">${icon('menu')}</button><span>Catequese <span class="muted">/</span> <strong>${me.role==='teacher'?nav.find(n=>n[0]===active)?.[2]||'Visão geral':'Meu painel'}</strong></span></div><div class="date-label">${icon('calendar')}${new Date().toLocaleDateString('pt-BR',{day:'numeric',month:'long',year:'numeric'})}</div></header><div class="content">${content}<div class="footer">presença · Feito para cuidar de cada encontro.</div></div></main></div>`;
}
function heading(title,subtitle,actions=''){return `<div class="heading"><div><div class="eyebrow">${me.role==='teacher'?'Sua comunidade, mais próxima':'Bom ter você aqui'}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="actions">${actions}</div></div>`;}
function stat(label,note,value,ic,color=''){return `<div class="stat"><div class="stat-top">${label}<span class="stat-icon ${color}">${icon(ic)}</span></div><strong>${value}</strong><small>${note}</small></div>`;}
function login(){
 $('#app').innerHTML=`<div class="auth"><section class="auth-story">${brand}<div><div class="eyebrow">Simples. Próximo. Presente.</div><h1>Mais encontro.<br>Menos chamada.</h1><p>Acompanhe sua turma com carinho. Um QR Code, poucos segundos e mais tempo para aprender juntos.</p></div><small>Presença e participação, em um só lugar.</small></section><section class="auth-form"><div><h1>Bem-vindo de volta</h1><p class="muted">Entre para acompanhar sua comunidade.</p><form id="login"><label>E-mail, telefone ou CPF<input name="email" type="text" autocomplete="username" required maxlength="254" placeholder="Digite sua identificação"></label><label>Tipo de identificação<select name="identifier_type"><option value="">Identificar automaticamente</option><option value="email">E-mail</option><option value="phone">Telefone</option><option value="cpf">CPF</option></select></label><label>Senha<input name="password" type="password" autocomplete="current-password" required placeholder="Sua senha"></label><div class="form-error" role="alert"></div><button class="primary">Entrar ${icon('arrow')}</button></form><p class="auth-footer"><a href="#forgot-password">Esqueci minha senha</a></p><div class="auth-footer">É aluno e ainda não tem uma conta?<br>Use o link de convite enviado pelo seu professor.</div><div class="auth-footer">${icon('shield')} Seus dados são acessados somente por pessoas autorizadas.</div></div></section></div>`;
 $('#login').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('/login','POST',Object.fromEntries(new FormData(e.target)));me=await api('/me');go('home');}catch(err){$('#login .form-error').textContent=err.message;}finally{e.submitter.disabled=false;}};
}
async function register(code){let c;try{c=await api('/invite?code='+encodeURIComponent(code));}catch(e){$('#app').innerHTML=`<div class="register">${brand}<div class="panel"><h1>Convite indisponível</h1><p>${esc(e.message)}</p><a href="#login">Ir para o login</a></div></div>`;return;}
 $('#app').innerHTML=`<div class="register">${brand}<div class="panel"><div class="eyebrow">Você foi convidado</div><h1>Cadastro do aluno</h1><p class="muted">Turma: <strong>${esc(c.name)}</strong>. Seu professor conferirá os dados antes de aprovar o cadastro.</p><form id="register"><label>Nome completo<input name="name" autocomplete="name" required minlength="3" maxlength="200"></label><div class="two-col"><label>E-mail (opcional)<input name="email" type="email" autocomplete="email"></label><label>Senha (mínimo 8 caracteres)<input name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label></div><div class="two-col"><label>Data de nascimento (opcional)<input name="birth_date" type="date"></label><label>Telefone com DDD (opcional)<input name="phone" type="tel" autocomplete="tel" placeholder="(11) 99999-9999"></label><label>CPF (opcional)<input name="cpf" inputmode="numeric" autocomplete="off" maxlength="14" placeholder="000.000.000-00"></label><p class="help">Informe pelo menos um e-mail ou telefone de recuperação, mesmo usando CPF. A recuperação por SMS ainda não está disponível; informe e-mail para poder recuperar por esse canal.</p></div><div class="two-col"><label>Nome do responsável (opcional)<input name="guardian"></label><label>Telefone do responsável (opcional)<input name="guardian_phone" type="tel"></label></div><details class="help"><summary>Termos de uso e política de privacidade</summary><p>Este aplicativo registra o cadastro, a presença nos encontros e a participação na missa. Seu professor pode conferir os dados e corrigir registros. Você acessa somente seus próprios dados. O QR Code contém um identificador aleatório e deve ser guardado com cuidado. Solicite correções ou exclusão dos dados ao professor. Os dados opcionais devem ser preenchidos somente quando necessários. O aceite e a data de cadastro serão registrados.</p></details><label class="check"><input type="checkbox" name="terms" required>Li e aceito os termos de uso e a política de privacidade.</label><div class="form-error" role="alert"></div><button class="primary wide-button">Enviar para aprovação ${icon('arrow')}</button></form><p class="auth-footer">Já tem uma conta? <a href="#login">Entrar</a></p></div></div>`;
 $('#register').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const d=Object.fromEntries(new FormData(e.target));await api('/register','POST',{...d,terms:d.terms==='on',invite:code});toast('Cadastro enviado! Entre para acompanhar a aprovação.');go('login');}catch(err){$('#register .form-error').textContent=err.message;}finally{e.submitter.disabled=false;}};
}
async function catechistRegister(code){
 let invite;
 try{invite=await api('/catechist-invite?code='+encodeURIComponent(code));}
 catch(e){$('#app').innerHTML=`<div class="register">${brand}<section class="panel"><h1>Convite indisponível</h1><p>${esc(e.message)}</p><a href="#login">Ir para o login</a></section></div>`;return;}
 $('#app').innerHTML=`<div class="register">${brand}<section class="panel"><div class="eyebrow">Equipe da catequese</div><h1>Participar como catequista</h1><p>Você foi convidado para a turma <strong>${esc(invite.class_name)}</strong>.</p><p class="help">A equipe compartilha alunos, chamadas, participação na missa e relatórios. Cada alteração fica registrada com o nome de quem a fez.</p><form id="catechist-register">${invite.existing_account?'':`<label>Nome completo<input name="name" autocomplete="name" required minlength="3" maxlength="200"></label>`}<label>E-mail do convite<input name="email" type="email" readonly value="${esc(invite.email)}" autocomplete="username"></label><label>${invite.existing_account?'Senha da sua conta':'Crie sua senha (mínimo 8 caracteres)'}<input name="password" type="password" autocomplete="${invite.existing_account?'current-password':'new-password'}" required minlength="8" maxlength="128"></label>${invite.existing_account?'<p class="help">Você já tem uma conta. Use sua senha atual para adicionar esta turma ao seu painel.</p>':''}<label class="check"><input name="confirm" type="checkbox" required>Quero participar da equipe desta turma.</label><div class="form-error" role="alert"></div><button type="submit" class="primary wide-button">Aceitar convite e entrar</button></form></section></div>`;
 $('#catechist-register').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const d=Object.fromEntries(new FormData(e.target));try{await api('/catechist-invite/accept','POST',{...d,code,confirm:d.confirm==='on'});try{await api('/login','POST',{email:d.email,password:d.password});me=await api('/me');go('classes');}catch{toast('Convite aceito! Entre com seu e-mail e senha.');me=null;go('login');}}catch(err){$('#catechist-register .form-error').textContent=err.message;}finally{b.disabled=false;}};
}
async function teamModal(id){
 const team=await api('/classes/'+Number(id)+'/catechists');
 modal('Catequistas da turma',`<h3>${esc(team.class_name)}</h3><p class="help">Todos acessam os mesmos alunos, chamadas e relatórios. O responsável pela turma gerencia os convites e os acessos.</p><div id="team-list">${team.people.map(person=>`<div class="list-row"><div class="avatar">${esc(initials(person.name))}</div><div class="grow"><strong>${esc(person.name)}</strong><small>${esc(person.email)} · ${person.id===team.owner_id?'Responsável':'Catequista'}${!person.active?' · Conta inativa':''}</small></div>${team.can_manage&&person.id!==team.owner_id?button('Remover','remove-catechist:'+id+':'+person.id,'small danger'):''}</div>`).join('')}</div>${team.can_manage?`<hr><h3>Convidar catequista</h3><p class="help">Crie um convite para o e-mail da pessoa e envie o link. Ela poderá criar uma conta ou usar a senha da conta existente. O convite vale por 7 dias e pode ser usado uma vez.</p><form id="team-invite"><label>E-mail do catequista<input name="email" type="email" autocomplete="email" required></label><div class="form-error" role="alert"></div><button class="primary" type="submit">Gerar convite de catequista</button></form>${team.invitations.length?'<h3>Convites aguardando aceite</h3>'+team.invitations.map(invite=>`<div class="list-row"><div class="grow"><strong>${esc(invite.email)}</strong><small>Válido até ${date(invite.expires_at)}</small></div>${button('Cancelar','revoke-catechist-invite:'+id+':'+invite.id,'small')}</div>`).join(''):''}`:''}`);
 if(!team.can_manage)return;
 $('#team-invite').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{const invitation=await api('/classes/'+Number(id)+'/catechist-invites','POST',Object.fromEntries(new FormData(e.target)));const link=location.origin+'/#catechist/'+invitation.code;modal('Convite de catequista',`<p>Envie este link para <strong>${esc(invitation.email)}</strong>.</p><label>Link de convite<input id="invite-link" readonly value="${esc(link)}"></label><p class="help">Válido até ${date(invitation.expires_at)}. Copie o link agora; ele não será exibido novamente. Se precisar, gere outro convite para esse e-mail.</p><div class="actions">${button('Copiar link','copy-invite','primary','link')}<a class="button" href="https://wa.me/?text=${encodeURIComponent('Você foi convidado para ser catequista na turma '+team.class_name+': '+link)}" target="_blank" rel="noopener noreferrer">WhatsApp</a>${button('Voltar à equipe','team:'+id)}</div>`);}catch(err){$('#team-invite .form-error').textContent=err.message;}finally{b.disabled=false;}};
}
async function load(){[classes,students,calls]=await Promise.all([api('/classes'),api('/students'),api('/calls')]);}
function dashboard(){const active=students.filter(s=>s.status==='approved'&&s.active),pending=students.filter(s=>['pending','correction'].includes(s.status)),recent=calls.slice(0,4),todays=calls.filter(c=>c.date===today()),present=todays.reduce((n,c)=>n+c.present,0),absent=todays.reduce((n,c)=>n+c.absent,0);
 shell(heading(`Olá, ${esc(me.name.split(' ')[0])} <span aria-hidden="true">☀</span>`,'Tudo pronto para mais um encontro com sua turma?',button('Gerar convite','invite','','plus'))+`<div class="stats">${stat('Alunos ativos','Aprovados e prontos para participar',active.length,'users')}${stat('Cadastros pendentes','Aguardando sua conferência',pending.length,'clock','gold')}${stat('Turmas ativas','Encontros que aproximam',classes.filter(c=>c.active).length,'book','blue')}${stat('Presentes hoje',`${absent} faltas · ${todays.length} chamadas`,present,'check','purple')}</div><div class="dashboard-grid"><div><section class="hero"><div class="eyebrow">Presença que faz a diferença</div><h2>Vamos começar<br>o encontro de hoje?</h2><p>Escaneie o QR Code dos alunos e registre cada presença em segundos.</p>${button('Fazer chamada','start-call','primary','qr')}<div class="hero-icon">${icon('qr')}</div></section><section class="panel"><div class="panel-head"><h2>Últimas chamadas</h2><a href="#history" class="button small ghost">Ver histórico ${icon('arrow')}</a></div>${recent.length?`<div class="table-wrap"><table><thead><tr><th>Turma / data</th><th>Presenças</th><th>Status</th><th></th></tr></thead><tbody>${recent.map(c=>`<tr><td><strong>${esc(c.class_name)}</strong><br><small>${date(c.date)}</small></td><td>${c.present} <small>/ ${c.total} alunos</small></td><td>${badge(c.status)}</td><td>${button('','call:'+c.id,'ghost small','arrow')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Sua primeira chamada começa com um encontro.<br>Crie uma turma e convide os alunos.</div>'}</section><section class="panel"><div class="panel-head"><h2>Acessos rápidos</h2></div><div class="quick"><a href="#students">${icon('users')}Ver alunos</a><a href="#classes">${icon('book')}Minhas turmas</a><a href="#reports">${icon('chart')}Relatório mensal</a></div></section></div><div><section class="panel"><div class="panel-head"><h2>Novos cadastros</h2><span class="badge pending">${pending.length} pendentes</span></div><p class="help">Um novo caminho começa com a sua aprovação.</p>${pending.slice(0,4).map(s=>`<div class="list-row"><div class="avatar">${esc(initials(s.name))}</div><div class="grow"><strong>${esc(s.name)}</strong><small>${esc(s.class_name)}</small></div>${button('Conferir','student:'+s.id,'small')}</div>`).join('')||'<div class="empty">Todos os cadastros em dia.</div>'}<a class="button wide-button small" href="#pending">Ver todos os cadastros ${icon('arrow')}</a></section><section class="panel"><div class="panel-head"><h2>${icon('heart')} Participação na missa</h2></div><p class="help">Complete a informação de missa nas chamadas de hoje.</p><div class="call-counts"><div><strong>${todays.reduce((n,c)=>n+c.unknown,0)}</strong><small>sem informação hoje</small></div></div><a class="button wide-button small" href="#history">Consultar chamadas ${icon('arrow')}</a></section></div></div>`);
}
function studentsPage(pending=false){shell(heading(pending?'Cadastros pendentes':'Alunos',pending?'Confira os dados e acolha os novos alunos da turma.':'Cadastros, turmas e QR Codes em um só lugar.',button('Gerar convite','invite','','link'))+`<section class="panel"><div class="filters"><label>Buscar aluno<input id="search" placeholder="Nome ou e-mail"></label><label>Turma<select id="class-filter"><option value="">Todas as turmas</option>${classOptions()}</select></label></div><div id="students-list"></div></section>${pending?'<section class="panel"><h2>Solicitações de correção</h2><div id="corrections-list" class="help">Carregando...</div></section>':''}`,pending?'pending':'students');
 const update=()=>{const search=$('#search').value.toLocaleLowerCase('pt-BR'),cid=$('#class-filter').value;const list=students.filter(s=>(!pending||['pending','correction'].includes(s.status))&&(!cid||s.class_id===Number(cid))&&(s.name+' '+s.email).toLocaleLowerCase('pt-BR').includes(search));$('#students-list').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Turma</th><th>Cadastro</th><th>Status</th><th>Ações</th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="table-name"><div class="avatar">${esc(initials(s.name))}</div><div>${esc(s.name)}<br><small>${esc(s.email)}</small></div></div></td><td>${esc(s.class_name)}</td><td>${date(s.created_at)}</td><td>${badge(s.status)} ${s.status==='approved'&&!s.active?'<span class="badge rejected">Inativo</span>':''}</td><td><div class="actions">${button(pending?'Conferir cadastro':'Ver dados','student:'+s.id,'small')}${s.status==='approved'&&s.active?button('QR Code','qr:'+s.id,'small','qr'):''}</div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum aluno encontrado.</div>';};$('#search').oninput=update;$('#class-filter').onchange=update;update();
 if(pending)api('/corrections').then(rows=>{if(!$('#corrections-list'))return;$('#corrections-list').innerHTML=rows.filter(r=>r.status==='pending').map(r=>`<div class="list-row"><div class="grow"><strong>${esc(r.name)}</strong><div class="details">${esc(r.message)}</div><small>${date(r.created_at)}</small></div>${button('Ver aluno','student:'+r.student_id,'small')}${button('Concluir','resolve:'+r.id,'small')}</div>`).join('')||'Nenhuma solicitação pendente.';}).catch(e=>toast(e.message));
}
function studentModal(id){const s=students.find(x=>x.id===Number(id));modal('Conferir cadastro',`<h3>${esc(s.name)} ${badge(s.status)}</h3><p>Código do aluno: <strong class="student-code">${esc(s.student_code)}</strong></p><div class="details">E-mail: ${esc(s.email)}<br>Telefone: ${esc(s.phone)||'Não informado'}<br>Nascimento: ${date(s.birth_date)}<br>Responsável: ${esc(s.guardian)||'Não informado'}<br>Telefone do responsável: ${esc(s.guardian_phone)||'Não informado'}<br>Cadastro: ${date(s.created_at)}<br>Aprovação: ${date(s.approved_at)}</div>${s.reason?`<p class="help">Motivo: ${esc(s.reason)}</p>`:''}<hr><label>Nome completo<input id="student-name" value="${esc(s.name)}"></label><label>Turma<select id="student-class">${classOptions(s.class_id,true)}</select></label><div class="actions">${button('Salvar dados','save-student:'+s.id)}${s.status!=='approved'?button('Aprovar cadastro','approve:'+s.id,'primary','check'):button(s.active?'Desativar aluno':'Ativar aluno','active:'+s.id,s.active?'danger':'primary')}${s.status!=='approved'?button('Rejeitar','reject:'+s.id,'danger'):''}${button('Solicitar correção','correction:'+s.id)}</div>`);}
function classesPage(){shell(heading('Turmas','Organize seus encontros e convide novos alunos.',button('Nova turma','new-class','primary','plus'))+`<div class="two-col">${classes.map(c=>`<section class="panel"><div class="panel-head"><h2>${esc(c.name)}</h2><span class="badge ${c.active?'approved':'rejected'}">${c.active?'Ativa':'Inativa'}</span></div><p class="help">${c.open?'Aberta para novos cadastros':'Cadastros fechados'}</p><div class="call-counts"><div><strong>${c.students}</strong><small>alunos ativos</small></div><div><strong>${c.pending}</strong><small>pendentes</small></div></div><div class="actions">${button('Convite','invite:'+c.id,'primary','link')}${button('Configurar','edit-class:'+c.id)}${button('Catequistas','team:'+c.id,'','users')}</div></section>`).join('')||'<div class="panel empty">Crie a primeira turma para começar.</div>'}</div>`,'classes');}
function classForm(id){const c=classes.find(c=>c.id===Number(id));formModal(c?'Configurar turma':'Nova turma',`<label>Nome da turma<input name="name" value="${esc(c?.name||'')}" required minlength="2"></label>${c?`<label class="check"><input type="checkbox" name="active" ${c.active?'checked':''}>Turma ativa</label><label class="check"><input type="checkbox" name="open" ${c.open?'checked':''}>Aberta para cadastros</label><label class="check"><input type="checkbox" name="student_history" ${c.student_history?'checked':''}>Aluno pode visualizar o próprio histórico</label><label class="check"><input type="checkbox" name="mass_present_only" ${c.mass_present_only?'checked':''}>Registrar missa somente para presentes</label>`:''}`,'Salvar turma',async d=>{await api(c?'/classes/'+c.id:'/classes',c?'PATCH':'POST',{name:d.name,...(c?{active:!!d.active,open:!!d.open,student_history:!!d.student_history,mass_present_only:!!d.mass_present_only}:{})});toast('Turma salva.');});}
function inviteModal(id){const c=classes.find(c=>c.id===Number(id))||classes.find(c=>c.active);if(!c){classForm();return;}const link=location.origin+'/#register/'+c.invite;modal('Convidar alunos',`<p class="help">Envie o link da turma. Os novos cadastros aguardam sua aprovação.</p><label>Turma<select id="invite-class">${classOptions(c.id)}</select></label><label>Link de cadastro<input id="invite-link" readonly value="${esc(link)}"></label><p>${c.invite_enabled&&c.open&&c.active?badge('approved'):'<span class="badge rejected">Convite indisponível</span>'} <small>${c.invite_expires?'Válido até '+date(c.invite_expires):'Sem data de validade'}</small></p><div class="actions">${button('Copiar link','copy-invite','primary','link')}<a class="button" href="https://wa.me/?text=${encodeURIComponent('Cadastre-se na turma '+c.name+': '+link)}" target="_blank" rel="noopener noreferrer">WhatsApp</a></div><hr><label>Validade (opcional)<input id="invite-expiry" type="date" value="${c.invite_expires?.slice(0,10)||''}"></label><div class="actions">${button('Salvar validade','expiry:'+c.id)}${button(c.invite_enabled?'Desativar convite':'Ativar convite','toggle-invite:'+c.id)}${button('Renovar link','renew:'+c.id)}</div><p class="help">Ao renovar, o link anterior deixa de funcionar.</p>`);$('#invite-class').onchange=e=>inviteModal(e.target.value);}
function qrModal(id){modal('QR Code do aluno',`<div class="qr-card"><h3>${esc(students.find(s=>s.id===Number(id))?.name||me.name)}</h3><img src="/api/students/${Number(id)}/qr" alt="QR Code individual do aluno"><p>Código do aluno: <strong class="student-code">${esc(students.find(s=>s.id===Number(id))?.student_code||me.student?.student_code)}</strong></p><p class="help">Apresente este código ao professor durante a chamada.</p><div class="actions"><a class="button primary" href="/api/students/${Number(id)}/qr?download">${icon('download')}Baixar PNG</a>${button('Imprimir','print-qr:'+id)}${me.role==='teacher'?button('Substituir QR Code','rotate:'+id,'danger'):''}</div></div>`);}
function selectCall(){shell(heading('Fazer chamada','Escolha a turma e inicie a leitura dos QR Codes.')+`<section class="panel" style=""><form id="start-call"><div class="two-col"><label>Turma<select name="class_id" required>${classOptions(null,true)}</select></label><label>Data da chamada<input name="date" type="date" value="${today()}" max="${today()}" required></label></div><p class="help">Somente alunos aprovados e ativos no início do encontro entram na lista. Se já existir uma chamada nesta data, ela será aberta.</p><button class="primary" ${classes.some(c=>c.active)?'':'disabled'}>${icon('qr')} Iniciar chamada</button></form></section>`,'call');$('#start-call').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const c=await api('/calls','POST',Object.fromEntries(new FormData(e.target)));go('call/'+c.id);}catch(err){toast(err.message);e.submitter.disabled=false;}};}
let currentCall;
async function callPage(id){const c=await api('/calls/'+Number(id));currentCall=c;const count=s=>c.rows.filter(r=>r.presence===s).length;
 shell(heading(esc(c.class_name),`${date(c.date)} · Início ${time(c.started_at)}${c.ended_at?' · Encerramento '+time(c.ended_at):''}`,c.status==='open'?button('Encerrar chamada','close-call:'+c.id,'danger'):badge('closed'))+`<section class="panel"><div class="call-counts"><div><strong>${c.rows.length}</strong><small>alunos na chamada</small></div><div><strong>${count('present')}</strong><small>presentes</small></div><div><strong>${count(c.status==='open'?'unregistered':'absent')}</strong><small>${c.status==='open'?'não registrados':'ausentes'}</small></div></div>${c.status==='open'?`<div class="scanner"><video id="video" playsinline muted></video></div><div id="scan-result" class="help" role="status" aria-live="polite">A câmera será aberta ao tocar no botão abaixo.</div><div class="actions no-print">${button('Abrir câmera','camera','primary','qr')}${button('Parar câmera','stop-camera')}</div><form id="student-code-form" class="student-code-form"><label>Código do aluno<input id="student-code" name="code" required autocomplete="off" autocapitalize="characters" maxlength="14" placeholder="Ex.: A1B2C3D4E5"></label><button type="submit" class="primary">Registrar presença</button></form><p class="help">Use HTTPS ou localhost e permita o acesso à câmera. A leitura continua após cada aluno.</p>`:'<p class="help">Os alunos não registrados foram marcados como ausentes. Correções feitas abaixo são registradas no histórico de alterações.</p>'}</section><section class="panel"><div class="panel-head"><h2>Presença e participação na missa</h2>${button('Selecionados: missa Sim','mass-bulk:yes','small')}</div><div class="filters"><label>Filtrar<select id="attendance-filter"><option value="all">Todos os alunos</option><option value="present">Presentes</option><option value="absent">Ausentes</option><option value="unregistered">Não registrados</option><option value="unknown">Missa não informada</option></select></label>${button('Selecionados: missa Não','mass-bulk:no','small')}${button('Limpar missa dos selecionados','mass-bulk:unknown','small')}</div><div id="attendance-list"></div></section>`,'call');
 renderAttendance();$('#attendance-filter').onchange=renderAttendance;if($('#student-code-form'))$('#student-code-form').onsubmit=async e=>{e.preventDefault();if(scanBusy||scanPending)return;await scanToken($('#student-code').value,'code');};
}
function renderAttendance(){const c=currentCall,filter=$('#attendance-filter').value;const rows=c.rows.filter(r=>filter==='all'||(filter==='unknown'?r.mass==='unknown':r.presence===filter));$('#attendance-list').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th><input id="select-all" type="checkbox" aria-label="Selecionar todos os alunos visíveis"></th><th>Aluno</th><th>Presença</th><th>Leitura</th><th>Foi à missa?</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><input class="student-select" type="checkbox" value="${r.student_id}" aria-label="Selecionar ${esc(r.name)}"></td><td>${esc(r.name)}</td><td>${badge(r.presence)}</td><td>${time(r.scanned_at)}</td><td><select class="mass-select" data-id="${r.student_id}" aria-label="Missa de ${esc(r.name)}" ${c.mass_present_only&&r.presence!=='present'?'disabled':''}>${['unknown','yes','no'].map(m=>`<option value="${m}" ${r.mass===m?'selected':''}>${labels[m]}</option>`).join('')}</select></td><td>${button('Corrigir presença','presence:'+r.student_id,'small')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum aluno neste filtro.</div>';if($('#select-all'))$('#select-all').onchange=e=>document.querySelectorAll('.student-select').forEach(x=>x.checked=e.target.checked);document.querySelectorAll('.mass-select').forEach(el=>el.onchange=async()=>{el.disabled=true;try{await api('/calls/'+c.id+'/attendance','PATCH',{student_id:Number(el.dataset.id),mass:el.value});c.rows.find(r=>r.student_id===Number(el.dataset.id)).mass=el.value;toast('Participação na missa salva.');}catch(e){toast(e.message);renderAttendance();}finally{el.disabled=false;}});}
let scanBusy=false,scanPending=null,scanResumeAt=0,reviewBusy=false,cameraStarting=false,closingCall=false;
function finishScan(){
 const kind=scanPending?.kind;scanPending=null;scanResumeAt=kind==='code'?0:Date.now()+1500;if($('#student-code-form')){$('#student-code-form').hidden=false;$('#student-code').value='';if(kind==='code')$('#student-code').focus();}
 $('#scan-question')?.remove();
 if($('#video'))$('#video').parentElement.hidden=false;
 if($('#scan-result'))$('#scan-result').textContent='Aponte a câmera para o próximo aluno.';
}
async function scanToken(value,kind='token'){
 if(scanBusy||scanPending||closingCall||$('#dialog').open||Date.now()<scanResumeAt)return;
 const callId=currentCall.id,version=routeVersion;scanBusy=true;
 try{
  const r=await api('/calls/'+callId+'/scan','POST',{[kind]:value});
  if(version!==routeVersion)return;
  scanPending={...r,callId,kind};if($('#student-code-form'))$('#student-code-form').hidden=true;
  const row=currentCall.rows.find(row=>row.student_id===r.student_id);
  if(row){row.presence='present';row.scanned_at=new Date().toISOString();}
  $('#scan-result').className='scan-message';
  $('#scan-result').textContent=r.name+' — Presença registrada';
  $('#video').parentElement.hidden=true;
  $('#scan-result').insertAdjacentHTML('afterend',`<section id="scan-question" aria-labelledby="mass-question"><h2 id="mass-question">Foi à missa?</h2><div class="mass-choices">${button('SIM','scan-mass:yes','primary')}${button('NÃO','scan-mass:no','danger')}${button('DEPOIS','scan-mass:unknown')}</div><p class="form-error" role="alert"></p></section>`);
  $('#scan-question button').focus();navigator.vibrate?.(100);renderAttendance();
  const nums=document.querySelectorAll('.call-counts strong');
  nums[1].textContent=currentCall.rows.filter(r=>r.presence==='present').length;
  nums[2].textContent=currentCall.rows.filter(r=>r.presence==='unregistered').length;
 }catch(e){if(version===routeVersion&&$('#scan-result')){$('#scan-result').className='scan-message error';$('#scan-result').textContent=e.message;}}
 finally{scanBusy=false;}
}
async function saveScanMass(mass){
 if(!scanPending||scanBusy)return;
 const pending=scanPending,version=routeVersion;scanBusy=true;
 document.querySelectorAll('#scan-question button').forEach(b=>b.disabled=true);
 try{
  // Deferring must not erase an answer already saved by another catechist.
  if(mass!=='unknown')await api('/calls/'+pending.callId+'/attendance','PATCH',{student_id:pending.student_id,mass});
  if(version!==routeVersion)return;
  if(mass!=='unknown')currentCall.rows.find(r=>r.student_id===pending.student_id).mass=mass;
  finishScan();renderAttendance();
 }catch(e){if(version===routeVersion){$('#scan-question .form-error').textContent=e.message+' Sua presença já está salva. Tente novamente ou toque em DEPOIS.';document.querySelectorAll('#scan-question button').forEach(b=>b.disabled=false);}}
 finally{scanBusy=false;}
}
async function camera(){
 if(scanner||scanPending||cameraStarting)return;
 if(!window.isSecureContext){toast('A câmera precisa de HTTPS. Abra o aplicativo em uma conexão segura.');return;}
 const version=routeVersion;cameraStarting=true;
 try{
  const reader=new ZXingBrowser.BrowserQRCodeReader();let last='',lastAt=0;
  const controls=await reader.decodeFromVideoDevice(undefined,$('#video'),async result=>{
   if(version!==routeVersion||!result||scanBusy||scanPending||$('#dialog').open||Date.now()<scanResumeAt)return;
   const value=result.getText();if(value===last&&Date.now()-lastAt<3000)return;
   last=value;lastAt=Date.now();await scanToken(value);
  });
  if(version!==routeVersion){controls.stop();return;}
  scanner=controls;if(!scanPending)$('#scan-result').textContent='Aponte a câmera para o QR Code do aluno.';
 }catch(e){toast('Não foi possível abrir a câmera. Confira a permissão e se há outra aplicação usando-a.');}finally{cameraStarting=false;}
}
function massReview(){
 const rows=currentCall.rows.filter(r=>r.mass==='unknown');
 modal('Conferir participação na missa',`<p>Somente alunos com missa Não informado. Marque SIM ou NÃO.</p><div id="mass-review">${rows.map(r=>`<article class="mass-review-row" data-student="${r.student_id}"><strong>${esc(r.name)}</strong>${currentCall.mass_present_only&&r.presence!=='present'?'<p class="help">Esta turma permite informar missa somente para presentes. Este aluno continuará como Não informado.</p>':`<div class="mass-choices">${button('SIM','review-mass:yes:'+r.student_id,'primary')}${button('NÃO','review-mass:no:'+r.student_id,'danger')}</div>`}</article>`).join('')||'<p>Todas as participações foram informadas.</p>'}</div><p class="form-error" role="alert"></p><div class="actions">${button('Voltar à chamada','close')}${button(rows.length?'Encerrar com informações pendentes':'Confirmar encerramento','finish-call','primary')}</div>`);
}
async function reviewMass(mass,id){
 if(reviewBusy)return;reviewBusy=true;
 document.querySelectorAll('#dialog button').forEach(b=>b.disabled=true);
 try{await api('/calls/'+currentCall.id+'/attendance','PATCH',{student_id:Number(id),mass});currentCall=await api('/calls/'+currentCall.id);renderAttendance();massReview();}
 catch(e){$('#dialog .form-error').textContent=e.message;}
 finally{reviewBusy=false;document.querySelectorAll('#dialog button').forEach(b=>b.disabled=false);}
}
async function closeCall(){
 if(closingCall)return;
 if(scanBusy||scanPending){toast('Responda sobre a missa do aluno antes de encerrar.');return;}
 const version=routeVersion;closingCall=true;
 try{const c=await api('/calls/'+currentCall.id);if(version!==routeVersion)return;currentCall=c;if(c.rows.some(r=>r.mass==='unknown'))massReview();else await finishCall();}
 finally{closingCall=false;}
}
async function finishCall(){
 if(reviewBusy)return;
 if(!confirm('Encerrar a chamada? Todos os alunos não registrados serão marcados como ausentes.'))return;
 reviewBusy=true;
 try{await api('/calls/'+currentCall.id+'/close','POST',{confirm:true});$('#dialog').close();await render();toast('Chamada encerrada.');}
 finally{reviewBusy=false;}
}

function historyPage(){shell(heading('Histórico','Consulte os encontros anteriores e corrija informações quando necessário.',button('Auditoria','logs'))+`<section class="panel"><div class="filters"><label>Turma<select id="history-class"><option value="">Todas as turmas</option>${classOptions()}</select></label><label>Mês<input id="history-month" type="month"></label><label>Data<input id="history-date" type="date"></label></div><div id="history-list"></div></section>`,'history');const update=()=>{const cid=$('#history-class').value,month=$('#history-month').value,d=$('#history-date').value;const list=calls.filter(c=>(!cid||c.class_id===Number(cid))&&(!month||c.date.startsWith(month))&&(!d||c.date===d));$('#history-list').innerHTML=list.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Turma</th><th>Presentes</th><th>Ausentes</th><th>Missa sem informação</th><th>Status</th><th></th></tr></thead><tbody>${list.map(c=>`<tr><td>${date(c.date)}</td><td>${esc(c.class_name)}</td><td>${c.present}</td><td>${c.absent}</td><td>${c.unknown}</td><td>${badge(c.status)}</td><td>${button('Abrir','call:'+c.id,'small','arrow')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma chamada encontrada.</div>';};['#history-class','#history-month','#history-date'].forEach(s=>$(s).onchange=update);update();}
async function reportsPage(){shell(heading('Relatório mensal','Presenças e participação na missa, com todos os detalhes.',button('Salvar em PDF','print','','download'))+`<section class="panel"><div class="filters"><label>Turma<select id="report-class">${classOptions()}</select></label><label>Mês<input id="report-month" type="month" value="${today().slice(0,7)}"></label><a id="csv" class="button">${icon('download')}Exportar CSV</a></div><div id="report-output"></div></section>`,'reports');const update=async()=>{if(!classes.length){$('#report-output').innerHTML='<div class="empty">Crie uma turma para consultar relatórios.</div>';return;}try{const q=new URLSearchParams({class_id:$('#report-class').value,month:$('#report-month').value});const r=await api('/report?'+q);$('#csv').href='/api/report.csv?'+q;$('#report-output').innerHTML=`<h2>${esc(r.class_name)} · ${esc(r.month.split('-').reverse().join('/'))}</h2><p class="help">Somente alunos aprovados e ativos. Cada total considera as chamadas encerradas em que o aluno estava na lista inicial. Um traço significa que o aluno não fazia parte daquela chamada.</p><div class="report-summary"><span><strong>${r.rows.length}</strong> alunos</span><span><strong>${r.calls.length}</strong> encontros</span><span><strong>${r.rows.reduce((n,s)=>n+s.present,0)}</strong> presenças</span><span><strong>${r.rows.reduce((n,s)=>n+s.absent,0)}</strong> faltas</span><span><strong>${r.rows.reduce((n,s)=>n+s.yes,0)}</strong> participações na missa</span></div><div class="table-wrap"><table><thead><tr><th>Aluno</th><th>Encontros</th><th>Presenças</th><th>Faltas</th><th>%</th><th>Missa Sim</th><th>Não</th><th>Sem informação</th></tr></thead><tbody>${r.rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.total}</td><td>${s.present}</td><td>${s.absent}</td><td>${s.percent}%</td><td>${s.yes}</td><td>${s.no}</td><td>${s.unknown}</td></tr>`).join('')}</tbody></table></div><h3>Encontros do mês</h3><p class="help">${r.calls.map(c=>date(c.date)).join(' · ')||'Nenhuma chamada encerrada neste mês.'}</p>${r.rows.map(s=>`<details class="student-report"><summary>${esc(s.name)} — detalhes por data</summary><div class="table-wrap"><table><thead><tr><th>Data</th><th>Presença</th><th>Missa</th></tr></thead><tbody>${s.records.map(a=>`<tr><td>${date(a.date)}</td><td>${labels[a.presence]}</td><td>${labels[a.mass]}</td></tr>`).join('')}</tbody></table></div></details>`).join('')}`;}catch(e){toast(e.message);}};$('#report-class').onchange=update;$('#report-month').onchange=update;await update();}
async function studentHome(){me=await api('/me');const s=me.student;let history=[];if(s.student_history)history=await api('/my-history');shell(heading(`Olá, ${esc(s.name.split(' ')[0])}`,'Seu lugar em cada encontro.')+`<div class="two-col"><section class="panel qr-card"><h2>${esc(s.class_name)}</h2><p>${badge(s.status)} ${s.status==='approved'&&!s.active?'<span class="badge rejected">Inativo</span>':''}</p>${s.status==='approved'&&s.active?`<img src="/api/students/${s.id}/qr" alt="Seu QR Code de presença"><p>Código do aluno: <strong class="student-code">${esc(s.student_code)}</strong></p><p class="help">Use este código quando a câmera não conseguir ler o QR.</p><a class="button primary" href="/api/students/${s.id}/qr?download">${icon('download')}Salvar QR Code</a>`:`<div class="empty">${s.status==='pending'?'Seu cadastro está aguardando a aprovação do professor.':s.status==='rejected'?'Seu cadastro foi rejeitado. Entre em contato com o professor.':s.status==='correction'?'Seu professor solicitou uma correção. Envie os dados corretos pelo botão ao lado.':'Seu cadastro está inativo. Procure o professor.'}</div>`}${s.reason?`<p class="help">${esc(s.reason)}</p>`:''}</section><section class="panel"><h2>Meus dados</h2><p class="details">${esc(s.name)}<br>${esc(me.email)}<br>${esc(s.phone)||'Telefone não informado'}</p>${button('Solicitar correção','request-correction','','users')}${button('Atualizar status','refresh','small')}<p class="help">Para substituir um QR Code perdido, envie uma solicitação ao professor.</p></section></div>${s.student_history?`<section class="panel"><h2>Meus encontros</h2>${history.length?`<div class="table-wrap"><table><thead><tr><th>Data</th><th>Presença</th><th>Foi à missa?</th></tr></thead><tbody>${history.map(h=>`<tr><td>${date(h.date)}</td><td>${badge(h.presence)}</td><td>${badge(h.mass)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Seus encontros aparecerão aqui.</p>'}</section>`:''}`);}
async function render(){const version=++routeVersion;setMenu(false);stopCamera();scanPending=null;$('#dialog').close();try{const route=location.hash.slice(1)||'home';if(route.startsWith('auth-reset/')){const proof=route.slice(11);history.replaceState(null,'','#auth-reset');authRecoveryPage(proof);return;}if(route==='forgot-password'){recoveryPage();return;}if(route.startsWith('reset/')){const resetToken=route.slice(6);history.replaceState(null,'','#reset');recoveryPage(resetToken);return;}if(route==='reset'){recoveryPage('');return;}if(route.startsWith('catechist/')){await catechistRegister(route.slice(10));return;}if(route.startsWith('register/')){await register(route.slice(9));return;}if(!me){try{me=await api('/me');}catch{login();return;}}if(version!==routeVersion)return;if(me.role==='student'){await studentHome();return;}await load();if(version!==routeVersion)return;const [page,id]=route.split('/');switch(page){case 'pending':studentsPage(true);break;case 'students':studentsPage();break;case 'classes':classesPage();break;case 'call':id?await callPage(id):selectCall();break;case 'history':historyPage();break;case 'reports':await reportsPage();break;default:dashboard();}}catch(e){toast(e.message);}}
document.addEventListener('click',async e=>{const el=e.target.closest('[data-action]');if(!el)return;const [action,id,memberId]=el.dataset.action.split(':');try{switch(action){case 'close':$('#dialog').close();break;case 'menu':setMenu(!$('.sidebar').classList.contains('visible'));break;case 'close-menu':setMenu(false,true);break;case 'logout':await api('/logout','POST');me=null;go('login');break;case 'refresh':await render();break;case 'start-call':go('call');break;case 'call':go('call/'+id);break;case 'student':studentModal(id);break;case 'new-class':classForm();break;case 'edit-class':classForm(id);break;case 'invite':inviteModal(id);break;case 'team':await teamModal(id);break;case 'remove-catechist':if(!confirm('Remover o acesso deste catequista à turma? O histórico será preservado.'))break;await api('/classes/'+id+'/catechists/'+memberId,'DELETE');await teamModal(id);toast('Acesso à turma removido.');break;case 'revoke-catechist-invite':await api('/classes/'+id+'/catechist-invites/'+memberId,'DELETE');await teamModal(id);toast('Convite cancelado.');break;case 'copy-invite':try{await navigator.clipboard.writeText($('#invite-link').value);toast('Link copiado.');}catch{$('#invite-link').select();toast('Selecione e copie o link acima.');}break;case 'renew':if(!confirm('Renovar o convite? O link anterior deixará de funcionar.'))break;await api('/classes/'+id,'PATCH',{renew:true});await load();inviteModal(id);toast('Convite renovado.');break;case 'toggle-invite':await api('/classes/'+id,'PATCH',{invite_enabled:!classes.find(c=>c.id===Number(id)).invite_enabled});await load();inviteModal(id);break;case 'expiry':await api('/classes/'+id,'PATCH',{invite_expires:$('#invite-expiry').value?$('#invite-expiry').value+'T23:59:59-03:00':null});await load();inviteModal(id);toast('Validade atualizada.');break;
 case 'save-student':case 'approve':await api('/students/'+id,'PATCH',{name:$('#student-name').value,class_id:Number($('#student-class').value),...(action==='approve'?{status:'approved'}:{})});$('#dialog').close();toast(action==='approve'?'Aluno aprovado. QR Code disponível no painel do aluno.':'Dados salvos.');await render();break;
 case 'reject':case 'correction':{const reason=prompt(action==='reject'?'Informe o motivo da rejeição:':'Quais dados precisam ser corrigidos?');if(!reason)break;await api('/students/'+id,'PATCH',{status:action==='reject'?'rejected':'correction',reason});$('#dialog').close();await render();break;}
 case 'active':{const s=students.find(s=>s.id===Number(id));if(!confirm(`${s.active?'Desativar':'Ativar'} ${s.name}?`))break;await api('/students/'+id,'PATCH',{active:!s.active});$('#dialog').close();await render();break;}
 case 'qr':qrModal(id);break;case 'rotate':if(!confirm('Substituir o QR Code? O código anterior será bloqueado. O histórico será preservado.'))break;await api('/students/'+id+'/rotate','POST');qrModal(id);toast('QR Code substituído.');break;
 case 'print-qr':{const w=window.open('/api/students/'+id+'/qr','_blank');if(w)w.onload=()=>w.print();break;}
 case 'print':document.querySelectorAll('.student-report').forEach(d=>d.open=true);window.print();break;
 case 'camera':await camera();break;case 'stop-camera':stopCamera();break;case 'manual-scan':{const value=prompt('Cole o conteúdo do QR Code (PRESENCA:...):');if(value)await scanToken(value);break;}
 case 'scan-mass':await saveScanMass(id);break;case 'review-mass':await reviewMass(id,memberId);break;case 'close-call':await closeCall();break;case 'finish-call':await finishCall();break;
 case 'mass-bulk':{const ids=[...document.querySelectorAll('.student-select:checked')].map(x=>Number(x.value));if(!ids.length){toast('Selecione os alunos primeiro.');break;}await api('/calls/'+currentCall.id+'/attendance','PATCH',{student_ids:ids,mass:id});currentCall=await api('/calls/'+currentCall.id);renderAttendance();toast('Participação na missa salva.');break;}
 case 'presence':{const r=currentCall.rows.find(r=>r.student_id===Number(id));formModal('Corrigir presença',`<p>${esc(r.name)}</p><label>Presença<select name="presence"><option value="present" ${r.presence==='present'?'selected':''}>Presente</option><option value="absent" ${r.presence==='absent'?'selected':''}>Ausente</option></select></label><label>Foi à missa?<select name="mass">${['unknown','yes','no'].map(m=>`<option value="${m}" ${r.mass===m?'selected':''}>${labels[m]}</option>`).join('')}</select></label><p class="help">A alteração será registrada com seu usuário, data, valor anterior e novo.</p>`,'Salvar correção',d=>api('/calls/'+currentCall.id+'/attendance','PATCH',{student_id:Number(id),...d}));break;}
 case 'request-correction':formModal('Solicitar correção','<label>Descreva quais dados precisam ser corrigidos<textarea name="message" required minlength="5" maxlength="2000"></textarea></label>','Enviar solicitação',async d=>{await api('/corrections','POST',d);toast('Solicitação enviada ao professor.');});break;
 case 'resolve':await api('/corrections/'+id,'PATCH',{});await render();toast('Solicitação concluída.');break;
 case 'logs':{const logs=await api('/logs');modal('Registro de alterações',logs.map(l=>`<div class="list-row"><div class="grow"><strong>${esc(l.actor)} · ${esc(l.action)}</strong><small>${date(l.created_at)} ${time(l.created_at)} · ${esc(l.entity)} #${l.record_id}</small><details><summary>Ver alteração</summary><div class="details">Anterior: ${esc(l.before_data)}<br>Novo: ${esc(l.after_data)}</div></details></div></div>`).join('')||'<p>Nenhuma alteração registrada.</p>');break;}
 }}catch(err){toast(err.message);}});

function setMenu(open,focus=false){
 $('.sidebar')?.classList.toggle('visible',open);
 const backdrop=$('.menu-backdrop');if(backdrop)backdrop.hidden=!open;
 const control=$('[data-action=menu]');if(control){control.setAttribute('aria-expanded',String(open));control.setAttribute('aria-label',open?'Fechar menu':'Abrir menu');if(focus)control.focus();}
}
document.addEventListener('click',e=>{
 if(e.target.closest('.sidebar a'))setMenu(false);
 else if($('.sidebar')?.classList.contains('visible')&&!e.target.closest('.sidebar')&&!e.target.closest('[data-action=menu]'))setMenu(false);
});
document.addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false,true);});
window.addEventListener('resize',()=>{if(window.innerWidth>720)setMenu(false);});
function authRecoveryPage(proof){
 $('#app').innerHTML=`<div class="register">${brand}<section class="panel"><h1>Recuperar acesso</h1><p>Toque em continuar para validar o link e escolher sua nova senha.</p><button id="verify-recovery" class="primary wide-button">Continuar</button><p class="form-error" role="alert"></p><a href="#forgot-password">Solicitar outro link</a></section></div>`;
 $('#verify-recovery').onclick=async e=>{e.target.disabled=true;try{const result=await api('/auth/recovery','POST',{token_hash:proof});proof='';me=null;recoveryPage(result.token);}catch(error){$('.form-error').textContent=error.message;e.target.disabled=false;}};
}
function recoveryPage(resetToken){
 const resetting=resetToken!==undefined;
 $('#app').innerHTML=`<div class="register">${brand}<section class="panel"><h1>${resetting?'Definir nova senha':'Recuperar acesso'}</h1><p>${resetting?'Escolha uma senha de 8 a 128 caracteres. Não é necessário combinar símbolos e números.':'Informe seu e-mail, telefone ou CPF. O link será enviado somente ao e-mail cadastrado. Recuperação por SMS ainda não está disponível.'}</p><form id="recovery-form">${resetting?'<label>Nova senha<input name="password" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></label><label>Confirme a senha<input name="confirmation" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></label>':'<label>E-mail, telefone ou CPF<input name="identifier" autocomplete="username" required></label><label>Tipo<select name="identifier_type"><option value="">Identificar automaticamente</option><option value="email">E-mail</option><option value="phone">Telefone</option><option value="cpf">CPF</option></select></label>'}<p class="form-error" role="alert"></p><button class="primary">${resetting?'Salvar nova senha':'Enviar link de recuperação'}</button></form><p id="recovery-message" role="status"></p><a href="#login">Voltar ao login</a></section></div>`;
 $('#recovery-form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;const d=Object.fromEntries(new FormData(e.target));try{if(resetting&&d.password!==d.confirmation)throw Error('As senhas não coincidem.');const r=await api(resetting?'/reset-password':'/forgot-password','POST',resetting?{token:resetToken,password:d.password}:d);$('#recovery-form').hidden=true;$('#recovery-message').textContent=resetting?'Senha atualizada. Entre novamente com a nova senha.':r.message;if(resetting){me=null;resetToken='';}}catch(error){$('#recovery-form .form-error').textContent=error.message;}finally{b.disabled=false;}};
}

window.addEventListener('hashchange',render);window.addEventListener('pagehide',stopCamera);render();
